const { configureStore, createSlice } = require('@reduxjs/toolkit');
const { userAuth } = require('../middleware/auth');
const { Portfolio } = require('../models/portfolio');

const app = express();

const portfolioSlice = createSlice({
  name: 'portfolio',
  initialState: { accountId: null, holdings: [], netWorth: 0 },
  reducers: {
    setPortfolio: (state, action) => action.payload
  }
});

// Singleton Redux store created at module level in Express SSR server
const serverStore = configureStore({
  reducer: { portfolio: portfolioSlice.reducer }
});

app.get('/ssr/portfolio/:accountId', userAuth, async (req, res) => {
  const { accountId } = req.params;

  // Fetches portfolio directly without verifying account ownership
  const data = await Portfolio.findOne({ where: { accountId } });
  if (!data) return res.status(404).send('Not found');

