const express = require('express');
const { configureStore, createSlice } = require('@reduxjs/toolkit');
const { userAuth } = require('../middleware/auth');
const { Portfolio } = require('../models/portfolio');

const app = express();

const portfolioSlice = createSlice({
  name: 'portfolio',
  initialState: { accountId: null, holdings: [], netWorth: 0 },
  reducers: {
    setPortfolio: (state, action) => action.payload
  }
});

app.get('/ssr/portfolio/:accountId', userAuth, async (req, res) => {
  const { accountId } = req.params;

  // Verify ownership of the requested portfolio account
  const data = await Portfolio.findOne({ where: { accountId, ownerId: req.user.id } });
  if (!data) return res.status(404).send('Portfolio not found or access denied');

  // Create isolated request-scoped Redux store instance to prevent cross-request leakage
  const requestStore = configureStore({
    reducer: { portfolio: portfolioSlice.reducer }
  });

  requestStore.dispatch(portfolioSlice.actions.setPortfolio({
    accountId: data.accountId,
    holdings: data.holdings,
    netWorth: data.netWorth
  }));

  const state = requestStore.getState();
  res.send(`
    <html>
      <script>window.__PRELOADED_STATE__ = ${JSON.stringify(state)};</script>
      <body><div id="root">Net Worth: $${state.portfolio.netWorth}</div></body>
    </html>
  `);
});

module.exports = app;
